def fib(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a
result = fib(4)

def primes(k):
    out = []
    x = 2
    while len(out) < k:
        if all(x % d for d in range(2, x)):
            out.append(x)
        x += 1
    return out
result = sum(primes(1))

